struct slr3_registry { char id[33]; slr3_record *records; size_t count,capacity; };

static int cp(char *d,size_t cap,const char *s){size_t n;if(!d||!cap||!s)return 0;n=strlen(s);if(n>=cap)return 0;memcpy(d,s,n+1);return 1;}
static int hx(const char*s,size_t n){size_t i;if(!s||strlen(s)!=n)return 0;for(i=0;i<n;++i)if(!isxdigit((unsigned char)s[i]))return 0;return 1;}
static int ident(const char*s,size_t cap,int dots){size_t i,n;if(!s||!(n=strlen(s))||n>=cap)return 0;if(!islower((unsigned char)s[0])&&!isdigit((unsigned char)s[0]))return 0;for(i=0;i<n;++i){unsigned char c=(unsigned char)s[i];if(!(islower(c)||isdigit(c)||c=='_'||c=='-'||(dots&&c=='.')))return 0;}return 1;}
static int utf8(const unsigned char*s){size_t i=0,n;if(!s)return 0;n=strlen((const char*)s);while(i<n){unsigned char c=s[i++];if(c<128)continue;if(c>=0xC2&&c<=0xDF){if(i>=n||(s[i]&0xC0)!=0x80)return 0;++i;}else if(c>=0xE0&&c<=0xEF){unsigned char a,b;if(i+1>=n)return 0;a=s[i];b=s[i+1];if((a&0xC0)!=0x80||(b&0xC0)!=0x80)return 0;if(c==0xE0&&a<0xA0)return 0;if(c==0xED&&a>=0xA0)return 0;i+=2;}else if(c>=0xF0&&c<=0xF4){unsigned char a,b,d;if(i+2>=n)return 0;a=s[i];b=s[i+1];d=s[i+2];if((a&0xC0)!=0x80||(b&0xC0)!=0x80||(d&0xC0)!=0x80)return 0;if(c==0xF0&&a<0x90)return 0;if(c==0xF4&&a>=0x90)return 0;i+=3;}else return 0;}return 1;}
static int state_ok(const char*s){static const char*v[]={"draft","discovered","inspected","registered","verified","available","offline","quarantined","deprecated","rejected","retired",NULL};int i;for(i=0;v[i];++i)if(!strcmp(s,v[i]))return 1;return 0;}
static int integrity_ok(const char*s){static const char*v[]={"unverified","intact","mismatch","unreadable","offline","quarantined",NULL};int i;for(i=0;v[i];++i)if(!strcmp(s,v[i]))return 1;return 0;}
static int payload_ok(const char*s){return !s[0]||!strcmp(s,"none")||!strcmp(s,"string")||!strcmp(s,"int")||!strcmp(s,"bool")||!strcmp(s,"region");}
static int record_ok(const slr3_record*r){size_t i;if(!r||!hx(r->id,32)||!ident(r->name_space,sizeof r->name_space,1)||!ident(r->kind,sizeof r->kind,1)||!r->schema_version[0]||!utf8((const unsigned char*)r->schema_version)||!r->name[0]||!utf8((const unsigned char*)r->name)||!state_ok(r->state)||!integrity_ok(r->integrity_status)||!payload_ok(r->payload_kind)||!r->revision)return 0;if(r->content_digest[0]&&!hx(r->content_digest,64))return 0;if(r->device_seal[0]&&!hx(r->device_seal,64))return 0;if(r->alias_count>SLR3_MAX_ALIASES||r->relationship_count>SLR3_MAX_RELATIONS)return 0;for(i=0;i<r->alias_count;++i)if(!r->aliases[i][0]||!utf8((const unsigned char*)r->aliases[i]))return 0;for(i=0;i<r->relationship_count;++i)if(!ident(r->relationships[i].type,32,0)||!hx(r->relationships[i].target_id,32))return 0;return 1;}
static slr3_record *findm(slr3_registry*r,const char*id){size_t i;if(!r||!id)return NULL;for(i=0;i<r->count;++i)if(!strcmp(r->records[i].id,id))return &r->records[i];return NULL;}
static int alias_conflict(const slr3_registry*r,const char*ns,const char*a,const char*except){size_t i,j;for(i=0;i<r->count;++i){const slr3_record*x=&r->records[i];if(except&&!strcmp(x->id,except))continue;if(strcmp(x->name_space,ns))continue;if(!strcmp(x->name,a))return 1;for(j=0;j<x->alias_count;++j)if(!strcmp(x->aliases[j],a))return 1;}return 0;}
static int rel_exists(const slr3_record*r,const char*t,const char*id){size_t i;for(i=0;i<r->relationship_count;++i)if(!strcmp(r->relationships[i].type,t)&&!strcmp(r->relationships[i].target_id,id))return 1;return 0;}
slr3_status slr3_id_from_seed(const char*seed,char out[33]){char d[65];if(!seed||!out)return SLR3_INVALID;sl_reg_sha256_hex(seed,strlen(seed),d);memcpy(out,d,32);out[32]=0;return SLR3_OK;}
slr3_registry *slr3_registry_create(const char*id,size_t max){slr3_registry*r;if(!hx(id,32))return NULL;r=(slr3_registry*)calloc(1,sizeof*r);if(!r)return NULL;if(!max)max=SLR3_DEFAULT_MAX;if(max>1000000){free(r);return NULL;}r->records=(slr3_record*)calloc(max,sizeof*r->records);if(!r->records){free(r);return NULL;}cp(r->id,sizeof r->id,id);r->capacity=max;return r;}
void slr3_registry_destroy(slr3_registry*r){if(r){free(r->records);free(r);}}
void slr3_record_init(slr3_record*r,const char*id,const char*ns,const char*kind,const char*name){if(!r)return;memset(r,0,sizeof*r);if(id)cp(r->id,sizeof r->id,id);if(ns)cp(r->name_space,sizeof r->name_space,ns);if(kind)cp(r->kind,sizeof r->kind,kind);if(name)cp(r->name,sizeof r->name,name);cp(r->schema_version,sizeof r->schema_version,"1");cp(r->state,sizeof r->state,"draft");cp(r->integrity_status,sizeof r->integrity_status,"unverified");r->revision=1;}
slr3_status slr3_registry_add(slr3_registry*r,const slr3_record*x){size_t i;if(!r||!record_ok(x))return SLR3_INVALID;if(r->count>=r->capacity)return SLR3_LIMIT;if(findm(r,x->id))return SLR3_EXISTS;if(alias_conflict(r,x->name_space,x->name,NULL))return SLR3_EXISTS;for(i=0;i<x->alias_count;++i)if(alias_conflict(r,x->name_space,x->aliases[i],NULL)||!strcmp(x->name,x->aliases[i]))return SLR3_EXISTS;r->records[r->count++]=*x;return SLR3_OK;}
const slr3_record *slr3_registry_get(const slr3_registry*r,const char*id){size_t i;if(!r||!id)return NULL;for(i=0;i<r->count;++i)if(!strcmp(r->records[i].id,id))return &r->records[i];return NULL;}
const slr3_record *slr3_registry_identify(const slr3_registry*r,const char*ns,const char*name){size_t i,j;if(!r||!ns||!name)return NULL;for(i=0;i<r->count;++i){const slr3_record*x=&r->records[i];if(strcmp(x->name_space,ns))continue;if(!strcmp(x->name,name))return x;for(j=0;j<x->alias_count;++j)if(!strcmp(x->aliases[j],name))return x;}return NULL;}
size_t slr3_registry_count(const slr3_registry*r){return r?r->count:0;}
const char *slr3_registry_id(const slr3_registry*r){return r?r->id:NULL;}
slr3_status slr3_registry_add_alias(slr3_registry*r,const char*id,const char*a){size_t j;slr3_record*x=findm(r,id);if(!x||!a||!a[0]||strlen(a)>=128||!utf8((const unsigned char*)a))return SLR3_INVALID;if(alias_conflict(r,x->name_space,a,x->id)||!strcmp(x->name,a))return SLR3_EXISTS;for(j=0;j<x->alias_count;++j)if(!strcmp(x->aliases[j],a))return SLR3_EXISTS;if(x->alias_count>=SLR3_MAX_ALIASES)return SLR3_LIMIT;cp(x->aliases[x->alias_count++],128,a);++x->revision;return SLR3_OK;}
slr3_status slr3_registry_relate(slr3_registry*r,const char*sid,const char*t,const char*tid){slr3_record*x=findm(r,sid);if(!x||!t||!tid||!ident(t,32,0)||!hx(tid,32))return SLR3_INVALID;if(!slr3_registry_get(r,tid))return SLR3_NOT_FOUND;if(rel_exists(x,t,tid))return SLR3_EXISTS;if(x->relationship_count>=SLR3_MAX_RELATIONS)return SLR3_LIMIT;cp(x->relationships[x->relationship_count].type,32,t);cp(x->relationships[x->relationship_count].target_id,33,tid);++x->relationship_count;++x->revision;return SLR3_OK;}
static slr3_status revision_ok(const slr3_record*x,uint64_t e){if(!x)return SLR3_NOT_FOUND;return x->revision==e?SLR3_OK:SLR3_CONFLICT;}
slr3_status slr3_registry_rename(slr3_registry*r,const char*id,const char*n,uint64_t e){slr3_record*x=findm(r,id);slr3_status s=revision_ok(x,e);if(s!=SLR3_OK)return s;if(!n||!n[0]||strlen(n)>=sizeof x->name||!utf8((const unsigned char*)n))return SLR3_INVALID;if(alias_conflict(r,x->name_space,n,x->id))return SLR3_EXISTS;cp(x->name,sizeof x->name,n);++x->revision;return SLR3_OK;}
slr3_status slr3_registry_set_locator(slr3_registry*r,const char*id,const char*l,uint64_t e){slr3_record*x=findm(r,id);slr3_status s=revision_ok(x,e);if(s!=SLR3_OK)return s;if(!l||strlen(l)>=sizeof x->locator||!utf8((const unsigned char*)l))return SLR3_INVALID;cp(x->locator,sizeof x->locator,l);++x->revision;return SLR3_OK;}
slr3_status slr3_registry_set_integrity(slr3_registry*r,const char*id,const char*v,uint64_t e){slr3_record*x=findm(r,id);slr3_status s=revision_ok(x,e);if(s!=SLR3_OK)return s;if(!v||!integrity_ok(v))return SLR3_INVALID;cp(x->integrity_status,sizeof x->integrity_status,v);++x->revision;return SLR3_OK;}
static int transition_ok(const char*a,const char*b){static const char*e[][2]={{"draft","discovered"},{"draft","registered"},{"draft","rejected"},{"discovered","inspected"},{"discovered","registered"},{"discovered","offline"},{"discovered","quarantined"},{"discovered","rejected"},{"inspected","registered"},{"inspected","verified"},{"inspected","quarantined"},{"registered","verified"},{"registered","offline"},{"registered","quarantined"},{"registered","deprecated"},{"verified","available"},{"verified","offline"},{"verified","quarantined"},{"verified","deprecated"},{"available","offline"},{"available","quarantined"},{"available","deprecated"},{"offline","discovered"},{"offline","inspected"},{"offline","verified"},{"offline","quarantined"},{"offline","retired"},{"quarantined","verified"},{"quarantined","rejected"},{"quarantined","retired"},{"deprecated","retired"},{"rejected","retired"},{NULL,NULL}};int i;for(i=0;e[i][0];++i)if(!strcmp(a,e[i][0])&&!strcmp(b,e[i][1]))return 1;return 0;}
