static slr3_status validate_all(const slr3_registry*r){size_t i,j,k;for(i=0;i<r->count;++i){const slr3_record*x=&r->records[i];if(!record_ok(x))return SLR3_MALFORMED;for(j=i+1;j<r->count;++j)if(!strcmp(x->id,r->records[j].id))return SLR3_EXISTS;if(alias_conflict(r,x->name_space,x->name,x->id))return SLR3_EXISTS;for(j=0;j<x->alias_count;++j){if(alias_conflict(r,x->name_space,x->aliases[j],x->id)||!strcmp(x->name,x->aliases[j]))return SLR3_EXISTS;for(k=j+1;k<x->alias_count;++k)if(!strcmp(x->aliases[j],x->aliases[k]))return SLR3_EXISTS;}for(j=0;j<x->relationship_count;++j){if(!slr3_registry_get(r,x->relationships[j].target_id))return SLR3_NOT_FOUND;for(k=j+1;k<x->relationship_count;++k)if(!strcmp(x->relationships[j].type,x->relationships[k].type)&&!strcmp(x->relationships[j].target_id,x->relationships[k].target_id))return SLR3_EXISTS;}}return SLR3_OK;}
slr3_status slr3_registry_load_v2(slr3_registry*r,const char*path){FILE*f;char line[SLR3_LINE_CAP],rid[33]="";slr3_registry*t=NULL;slr3_record x;int in=0,have=0,bad=0;unsigned long long seen=0;if(!r||!path)return SLR3_INVALID;f=fopen(path,"rb");if(!f)return SLR3_IO;if(!fgets(line,sizeof line,f)){fclose(f);return SLR3_MALFORMED;}line[strcspn(line,"\r\n")]=0;if(strcmp(line,"SLREG 2")){fclose(f);return SLR3_MALFORMED;}while(fgets(line,sizeof line,f)){char*eq;size_t n=strlen(line);if(n&&line[n-1]!='\n'&&!feof(f)){bad=1;break;}line[strcspn(line,"\r\n")]=0;if(!line[0])continue;if(!strcmp(line,"record")){if(in||!have){bad=1;break;}memset(&x,0,sizeof x);cp(x.schema_version,sizeof x.schema_version,"1");cp(x.state,sizeof x.state,"draft");cp(x.integrity_status,sizeof x.integrity_status,"unverified");x.revision=1;seen=0;in=1;continue;}if(!strcmp(line,"end")){unsigned long long req=(1ULL<<0)|(1ULL<<1)|(1ULL<<2)|(1ULL<<3)|(1ULL<<4)|(1ULL<<5)|(1ULL<<22);if(!in||(seen&req)!=req||!record_ok(&x)||t->count>=t->capacity){bad=1;break;}t->records[t->count++]=x;in=0;continue;}eq=strchr(line,'=');if(!eq){bad=1;break;}*eq++=0;if(in){if(!assign(&x,line,eq,&seen)){bad=1;break;}}else{char z[64];if(strcmp(line,"registry")||have||!decode(eq,z,sizeof z)||!hx(z,32)){bad=1;break;}cp(rid,sizeof rid,z);have=1;t=slr3_registry_create(rid,r->capacity);if(!t){bad=1;break;}}}if(ferror(f))bad=1;fclose(f);if(in||!have||!t)bad=1;if(!bad&&validate_all(t)!=SLR3_OK)bad=1;if(bad){slr3_registry_destroy(t);return SLR3_MALFORMED;}free(r->records);r->records=t->records;r->count=t->count;r->capacity=t->capacity;memcpy(r->id,t->id,sizeof r->id);t->records=NULL;slr3_registry_destroy(t);return SLR3_OK;}

static void trim(char*s){size_t n;while(*s&&isspace((unsigned char)*s))memmove(s,s+1,strlen(s));n=strlen(s);while(n&&isspace((unsigned char)s[n-1]))s[--n]=0;}
static int splitprov(char*line,char f[7][256]){char*p=line;int i;for(i=0;i<7;++i){char*sep;if(i<6){sep=strstr(p," | ");if(!sep)return 0;*sep=0;}else sep=NULL;if(strlen(p)>=256)return 0;strcpy(f[i],p);trim(f[i]);if(i<6)p=sep+3;}return 1;}
static slr3_status add_key(slr3_registry*r,const char*path,char out[33]){char seed[512];slr3_record x;if(snprintf(seed,sizeof seed,"legacy-key|%s",path)>=(int)sizeof seed)return SLR3_INVALID;slr3_id_from_seed(seed,out);slr3_record_init(&x,out,"sleela.compat","legacy_key",path[0]?path:"(root)");cp(x.state,sizeof x.state,"registered");cp(x.locator,sizeof x.locator,path);return slr3_registry_add(r,&x);}
static slr3_status add_value(slr3_registry*r,const char*path,const char*kid,const char*name,char type,const char*v){char seed[768],display[512],rid[33];slr3_record x;slr3_status s;if(snprintf(seed,sizeof seed,"legacy-value|%s|%s",path,name)>=(int)sizeof seed||snprintf(display,sizeof display,"%s/%s",path,name)>=(int)sizeof display)return SLR3_INVALID;slr3_id_from_seed(seed,rid);slr3_record_init(&x,rid,"sleela.compat","setting",display);cp(x.state,sizeof x.state,"registered");cp(x.locator,sizeof x.locator,path);if(type=='s'){cp(x.payload_kind,sizeof x.payload_kind,"string");if(!cp(x.payload,sizeof x.payload,v))return SLR3_INVALID;}else if(type=='i'){char*e=NULL;errno=0;(void)strtol(v,&e,10);if(errno||!e||e==v||*e)return SLR3_MALFORMED;cp(x.payload_kind,sizeof x.payload_kind,"int");cp(x.payload,sizeof x.payload,v);}else if(type=='b'){if(strcmp(v,"0")&&strcmp(v,"1"))return SLR3_MALFORMED;cp(x.payload_kind,sizeof x.payload_kind,"bool");cp(x.payload,sizeof x.payload,v);}else return SLR3_MALFORMED;s=slr3_registry_add(r,&x);if(s!=SLR3_OK)return s;return slr3_registry_relate(r,x.id,"belongs_to",kid);}
