slr3_status slr3_registry_migrate_v1(const char*in,const char*out,const char*rid,size_t max){FILE*f;char line[SLR3_LINE_CAP],path[256]="",kid[33]="";slr3_registry*r;slr3_status s=SLR3_OK;if(!in||!out||!rid)return SLR3_INVALID;f=fopen(in,"rb");if(!f)return SLR3_IO;if(!fgets(line,sizeof line,f)){fclose(f);return SLR3_MALFORMED;}line[strcspn(line,"\r\n")]=0;if(strcmp(line,"SLREG 1")){fclose(f);return SLR3_MALFORMED;}r=slr3_registry_create(rid,max);if(!r){fclose(f);return SLR3_INVALID;}while(fgets(line,sizeof line,f)){char*p;size_t n=strlen(line);if(n&&line[n-1]!='\n'&&!feof(f)){s=SLR3_MALFORMED;break;}line[strcspn(line,"\r\n")]=0;if(!line[0])continue;if(line[0]=='['){char*e=strchr(line,']');if(!e||e[1]||(size_t)(e-line-1)>=sizeof path){s=SLR3_MALFORMED;break;}*e=0;cp(path,sizeof path,line+1);s=add_key(r,path,kid);if(s!=SLR3_OK)break;}else if(line[0]=='='&&line[1]==' '&&line[3]==' '){char type=line[2],name[64],value[1024];char*sp;if(!kid[0]){s=SLR3_MALFORMED;break;}p=line+4;sp=strchr(p,' ');{size_t z=sp?(size_t)(sp-p):strlen(p);if(!z||z>=sizeof name){s=SLR3_MALFORMED;break;}memcpy(name,p,z);name[z]=0;if(sp){if(!cp(value,sizeof value,sp+1)){s=SLR3_INVALID;break;}}else value[0]=0;}s=add_value(r,path,kid,name,type,value);if(s!=SLR3_OK)break;}else if(line[0]=='@'){if(!kid[0]){s=SLR3_MALFORMED;break;}p=line+1;while(*p==' ')++p;s=add_prov(r,path,kid,p);if(s!=SLR3_OK)break;}else{s=SLR3_MALFORMED;break;}}if(ferror(f))s=SLR3_IO;fclose(f);if(s==SLR3_OK)s=validate_all(r);if(s==SLR3_OK)s=slr3_registry_save_v2(r,out);slr3_registry_destroy(r);return s;}
slr3_status slr3_registry_review(const slr3_registry*r,char*b,size_t cap){size_t i,used=0;if(!r||!b||!cap)return SLR3_INVALID;{int n=snprintf(b,cap,"SLeeLa Registry 3.0 id=%s records=%zu\n",r->id,r->count);if(n<0)return SLR3_IO;used=(size_t)n;}for(i=0;i<r->count&&used<cap;++i){const slr3_record*x=&r->records[i];int n=snprintf(b+used,cap-used,"[%s] %s kind=%s state=%s rev=%" PRIu64 " integrity=%s\n",x->name_space,x->name,x->kind,x->state,x->revision,x->integrity_status);if(n<0)return SLR3_IO;used+=(size_t)n;}return used<cap?SLR3_OK:SLR3_LIMIT;}
const char *slr3_status_name(slr3_status s){switch(s){case SLR3_OK:return"ok";case SLR3_INVALID:return"invalid";case SLR3_NOT_FOUND:return"not_found";case SLR3_EXISTS:return"exists";case SLR3_LIMIT:return"limit";case SLR3_MALFORMED:return"malformed";case SLR3_IO:return"io_error";case SLR3_CONFLICT:return"revision_conflict";case SLR3_BAD_TRANSITION:return"bad_transition";case SLR3_INTEGRITY:return"integrity_required";default:return"unknown";}}
